mapper.select:
SELECT FROM release_asset a WHERE a.release_id IN
#{id}
ORDER BY a.release_id ASC, a.platform ASC, a.package_type ASC

SELECT t.id, t.software_id, t.version, t.channel, t.notes_zh, t.notes_en, t.published_at, t.status, t.created_at FROM ( SELECT r.id, r.software_id, r.version, r.channel, r.notes_zh, r.notes_en, r.published_at, r.status, r.created_at, ROW_NUMBER() OVER (PARTITION BY r.software_id ORDER BY r.published_at DESC, r.id DESC) AS rn FROM software_release r WHERE r.status = 1 AND r.software_id IN
#{id}
) t WHERE t.rn = 1

SELECT s.id AS software_id, COALESCE(SUM(a.download_count), 0) AS total FROM software s LEFT JOIN software_release r ON r.software_id = s.id AND r.status = 1 LEFT JOIN release_asset a ON a.release_id = r.id WHERE s.id IN
#{id}
GROUP BY s.id
